// LeetCode 261 — do these undirected edges on nodes 0..n-1 form exactly one tree?
public static class ValidTree {
    public static bool Check(int n, int[][] edges) {
        edges ??= new int[0][];
        // A tree on n nodes has exactly n - 1 edges. With that many, "no cycle" also means "connected".
        if (edges.Length != n - 1) return false;
        var parent = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;
        foreach (var e in edges) {
            int a = Root(parent, e[0]), b = Root(parent, e[1]);
            if (a == b) return false;          // already connected: this edge closes a cycle
            parent[a] = b;                     // join the two groups
        }
        return true;
    }

    // Union-find root with path halving: each lookup shortens the path for the next one.
    private static int Root(int[] parent, int x) {
        while (parent[x] != x) { parent[x] = parent[parent[x]]; x = parent[x]; }
        return x;
    }
}
